# --- 100건으로 재 본다 ---

@DisplayName("deleteAllInBatch 는 테이블당 한 번만 나간다")
@Test
void deleteAllInBatchQueryCount() {
    // given
    List<Product> products = IntStream.rangeClosed(1, 100)
            .mapToObj(i -> createProduct(String.format("%03d", i), 4000))
            .toList();
    productRepository.saveAll(products);

    Statistics stats = statistics();
    stats.clear();

    // when
    productRepository.deleteAllInBatch();

    // then
    assertThat(stats.getPrepareStatementCount()).isEqualTo(1);
}

$ ./gradlew test --tests CleanupQueryTest

Hibernate: delete from product

CleanupQueryTest > deleteAllInBatch 는 테이블당 한 번만 나간다 PASSED

#   1개다

# --- deleteAll 로 바꾸면 ---

productRepository.deleteAll();

assertThat(stats.getPrepareStatementCount()).isEqualTo(1);

$ ./gradlew test --tests CleanupQueryTest

Hibernate: select p1_0.id, ... from product p1_0
Hibernate: delete from product where id=?
Hibernate: delete from product where id=?
... (100번)

CleanupQueryTest > deleteAllInBatch 는 테이블당 한 번만 나간다 FAILED
    org.opentest4j.AssertionFailedError:
    expected: 1L
     but was: 101L

#   101개다

#   5.9절에서는 두 건이라 12개였다
#   100건이면 101개다

#   행 수에 비례한다

# --- 시간도 재 보면 ---

#   deleteAllInBatch
INFO  TimerAspect : cleanup took 3ms

#   deleteAll
INFO  TimerAspect : cleanup took 87ms

#   29배다

#   테스트 40개면 정리에만 3.5초가 든다

# --- cascade 가 있으면 ---

@Entity
public class Order {
    @OneToMany(mappedBy = "order", cascade = ALL, orphanRemoval = true)
    private List<OrderProduct> orderProducts = new ArrayList<>();
}

#   deleteAll 로

orderRepository.deleteAll();

Hibernate: select o1_0.id, ... from orders o1_0
Hibernate: select op1_0.order_id, ... from order_product op1_0
           where op1_0.order_id=?
Hibernate: delete from order_product where id=?
Hibernate: delete from order_product where id=?
Hibernate: delete from orders where id=?

CleanupQueryTest > cascadeDelete() PASSED

#   order_product 를 알아서 지웠다

#   deleteAllInBatch 로

orderRepository.deleteAllInBatch();

Hibernate: delete from orders

CleanupQueryTest > cascadeDelete() FAILED
    org.springframework.dao.DataIntegrityViolationException:
    Referential integrity constraint violation:
    "FK_ORDER_PRODUCT_ORDER: PUBLIC.ORDER_PRODUCT FOREIGN KEY(ORDER_ID)
     REFERENCES PUBLIC.ORDERS(ID)"

#   cascade 를 무시하고 orders 만 지웠다

#   그래서 5.9절에서 순서를 손으로 챙겼다

# --- 정리 순서를 지키면 ---

orderProductRepository.deleteAllInBatch();
orderRepository.deleteAllInBatch();

Hibernate: delete from order_product
Hibernate: delete from orders

CleanupQueryTest > cascadeDelete() PASSED

#   2개다

#   deleteAll 판은 주문 100건에 상품 2개씩이면
#   1 + 100 + 200 + 100 = 401 개다

