@DisplayName("주문 목록 조회는 쿼리 3개로 끝난다")
@Test
void orderQueryCount() {
    주문_10건_저장();
    Statistics stats = statistics();
    stats.clear();

    orderService.findOrders(0, 10);

    assertThat(stats.getPrepareStatementCount()).isEqualTo(3);
}

